async function api(url, options = {}) { const headers = {...(options.headers || {})}; if (options.body && !headers['Content-Type']) headers['Content-Type'] = 'application/json'; const response = await fetch(url, {...options, headers}); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.error || response.statusText); } return response.json(); }
