async function loadFeed() { const params = new URLSearchParams({sort: $('#sort').value, limit: '100'}); if ($('#source-filter').value) params.set('source', $('#source-filter').value); if ($('#category-filter').value) params.set('signalCategory', $('#category-filter').value); if ($('#status-filter').value) params.set('status', $('#status-filter').value); if ($('#min-quality').value) params.set('minQuality', $('#min-quality').value); const data = await api(`/api/opportunities?${params}`); state.opportunities = data.opportunities; renderFeed(); $('#updated-label').textContent = `updated ${new Date().toLocaleTimeString()} · ${data.total} total`; }
