async function loadMarketTaxonomy() { const data = await api('/api/market/taxonomy/technologies'); $('#market-taxonomy').innerHTML = (data.terms || []).map((term) => '<div class=\'health-row\'><span>' + esc(term.canonical) + ' · ' + esc(term.alias) + '</span><button type=\'button\' class=\'button secondary taxonomy-toggle\' data-canonical=\'' + esc(term.canonical) + '\' data-alias=\'' + esc(term.alias) + '\' data-enabled=\'' + String(term.enabled !== false) + '\'>' + (term.enabled === false ? 'Enable' : 'Disable') + '</button></div>').join('') || '<p class=\'subtle\'>No taxonomy terms configured.</p>'; document.querySelectorAll('.taxonomy-toggle').forEach((button) => button.addEventListener('click', async () => { await api('/api/market/taxonomy/technologies', { method: 'PATCH', body: JSON.stringify({ canonical: button.dataset.canonical, alias: button.dataset.alias, enabled: button.dataset.enabled !== 'true' }) }); await loadMarketTaxonomy(); })); }
