loadMarketSignals = async function() { const data = await api('/api/market/signals?limit=25'); $('#market-signals').innerHTML = data.signals?.length ? data.signals.map((signal) => { const evidenceCount = Array.isArray(signal.supporting_listing_ids) ? signal.supporting_listing_ids.length : 0; const ratio = signal.change_ratio === null || signal.change_ratio === undefined ? 'baseline unavailable' : Number(signal.change_ratio).toFixed(1) + '× baseline'; const subject = signal.scope === 'company' && signal.employer_id ? '<a href=\'#\' class=\'market-signal-company source-link\' data-company-id=\'' + esc(signal.employer_id) + '\'>' + esc(signal.employer_name || 'Company') + '</a>' : '<span>' + esc(signal.dimension ? 'Market · ' + signal.dimension : 'Market') + '</span>'; return '<div class=\'signal-row\'><div><strong>' + subject + '</strong><div class=\'subtle\'>' + esc(signal.explanation) + '</div><div class=\'health-detail\'>' + esc(signal.signal_type.replaceAll('_', ' ')) + ' · ' + esc(String(signal.period_start)) + ' → ' + esc(String(signal.period_end)) + ' · ' + esc(ratio) + ' · ' + Number(signal.sample_size || 0).toLocaleString() + ' baseline days · ' + evidenceCount + ' supporting listings</div></div><div class=\'signal-actions\'><span class=\'pill\'>' + Number(signal.observed_value || 0).toLocaleString() + ' observed</span><button type=\'button\' class=\'button secondary market-signal-evidence-button\' data-signal-id=\'' + esc(signal.id) + '\'>View evidence</button></div></div>'; }).join('') : '<p class=\'subtle\'>No sufficiently supported signals yet.</p>'; document.querySelectorAll('.market-signal-company').forEach((link) => link.addEventListener('click', (event) => { event.preventDefault(); openCompany(link.dataset.companyId).catch(console.error); })); document.querySelectorAll('.market-signal-evidence-button').forEach((button) => button.addEventListener('click', () => loadMarketSignalEvidence(button.dataset.signalId).catch((error) => { $('#market-signal-evidence').classList.remove('hidden'); $('#market-signal-evidence').innerHTML = '<p class=\'subtle\'>' + esc(error.message) + '</p>'; }))); };
